-- Seed translations for existing DB content (generated). Safe to re-run.

on conflict (product_id, locale) do update set
  description = excluded.description,
  size_description = excluded.size_description,
  product_details = excluded.product_details,
  updated_at = now();

on conflict (help_id, locale) do update set
  title = excluded.title,
  subtitle = excluded.subtitle,
  description = excluded.description,
  updated_at = now();

on conflict (page_id, locale) do update set
  title = excluded.title,
  content = excluded.content,
  updated_at = now();
