insert into public.product_translations (product_id, locale, description, size_description, product_details) values
  (25, 'el', E'Το Cole T-Shirt έχει χαλαρή γραμμή και είναι φτιαγμένο από μαλακό οργανικό βαμβάκι, με μικρό τύπωμα στο στήθος και μεγάλο σχέδιο με σκηνή τραπεζιού στην πλάτη.', E'Κανονική εφαρμογή', E'- 100% βαμβάκι\r\n- Λογότυπο στο στήθος\r\n- Στενή εφαρμογή\r\n- Κανονική ραφή ώμου\r\n- Ριμπ τελειώματα\r\n- Τσέπη καγκουρό\r\n- Ετικέτα brand στο τελείωμα'),
  (25, 'da', E'Cole T-shirten har en løs pasform i blød økologisk bomuld med et lille print på brystet og et stort motiv med en bordscene på ryggen.', E'Regular fit', E'- 100 % bomuld\r\n- Logo på brystet\r\n- Slim fit\r\n- Almindelig skuldersøm\r\n- Ribkanter\r\n- Kængurulomme\r\n- Brandlabel ved kanten'),
  (25, 'de', E'Das Cole T-Shirt ist locker geschnitten aus weicher Bio-Baumwolle, mit kleinem Print auf der Brust und großem Tisch-Motiv auf dem Rücken.', E'Reguläre Passform', E'- 100 % Baumwolle\r\n- Markenschriftzug auf der Brust\r\n- Slim Fit\r\n- Normale Schulternaht\r\n- Gerippte Säume\r\n- Kängurutasche\r\n- Markenlabel am Saum'),
  (36, 'el', E'Το Cole T-Shirt έχει χαλαρή γραμμή και είναι φτιαγμένο από μαλακό οργανικό βαμβάκι, με μικρό τύπωμα στο στήθος και μεγάλο σχέδιο με σκηνή τραπεζιού στην πλάτη.', E'Χαλαρή εφαρμογή', E'- 100% βαμβάκι\r\n- Λογότυπο στο στήθος\r\n- Στενή εφαρμογή\r\n- Κανονική ραφή ώμου\r\n- Ριμπ τελειώματα\r\n- Τσέπη καγκουρό\r\n- Ετικέτα brand στο τελείωμα'),
  (36, 'da', E'Cole T-shirten har en løs pasform i blød økologisk bomuld med et lille print på brystet og et stort motiv med en bordscene på ryggen.', E'Løs pasform', E'- 100 % bomuld\r\n- Logo på brystet\r\n- Slim fit\r\n- Almindelig skuldersøm\r\n- Ribkanter\r\n- Kængurulomme\r\n- Brandlabel ved kanten'),
  (36, 'de', E'Das Cole T-Shirt ist locker geschnitten aus weicher Bio-Baumwolle, mit kleinem Print auf der Brust und großem Tisch-Motiv auf dem Rücken.', E'Lockere Passform', E'- 100 % Baumwolle\r\n- Markenschriftzug auf der Brust\r\n- Slim Fit\r\n- Normale Schulternaht\r\n- Gerippte Säume\r\n- Kängurutasche\r\n- Markenlabel am Saum'),
  (37, 'el', E'Ένα μινιμαλιστικό κομμάτι που φοριέται όλο τον χρόνο. Το Konrad έχει άνετη κανονική εφαρμογή και είναι σχεδιασμένο να φοριέται έξω από το παντελόνι.', E'Κανονική εφαρμογή', E'- 100% βαμβάκι\r\n- Λογότυπο στο στήθος\r\n- Στενή εφαρμογή\r\n- Κανονική ραφή ώμου\r\n- Ριμπ τελειώματα\r\n- Τσέπη καγκουρό\r\n- Ετικέτα brand στο τελείωμα'),
  (37, 'da', E'Et minimalistisk stykke, du kan bruge hele året. Konrad har en afslappet regular fit, der er designet til at blive båret udenpå bukserne.', E'Regular fit', E'- 100 % bomuld\r\n- Logo på brystet\r\n- Slim fit\r\n- Almindelig skuldersøm\r\n- Ribkanter\r\n- Kængurulomme\r\n- Brandlabel ved kanten'),
  (37, 'de', E'Ein minimalistisches Teil für das ganze Jahr. Das Konrad hat eine lässige reguläre Passform und ist dafür gemacht, offen über der Hose getragen zu werden.', E'Reguläre Passform', E'- 100 % Baumwolle\r\n- Markenschriftzug auf der Brust\r\n- Slim Fit\r\n- Normale Schulternaht\r\n- Gerippte Säume\r\n- Kängurutasche\r\n- Markenlabel am Saum'),
  (38, 'el', E'Αυτή η έκδοση της σειράς Como έχει κλασικό κανονικό κόψιμο με στενό τελείωμα στο πόδι και ελαστική μέση με κορδόνι. Συνδυάζεται εύκολα με τα πάντα, από πλεκτά μέχρι ασορτί σακάκι.\n\n- 65% πολυεστέρας (ανακυκλωμένος), 35% βισκόζη\n- Κανονική εφαρμογή με τσάκιση και στενό πόδι\n- Κλείσιμο με φερμουάρ και κουμπί\n- Ελαστική μέση με κορδόνι\n- Πλαϊνές και πίσω τσέπες', E'Κανονική εφαρμογή', E'- 100% βαμβάκι\r\n- Λογότυπο στο στήθος\r\n- Στενή εφαρμογή\r\n- Κανονική ραφή ώμου\r\n- Ριμπ τελειώματα\r\n- Τσέπη καγκουρό\r\n- Ετικέτα brand στο τελείωμα'),
  (38, 'da', E'Denne udgave af vores Como-serie har et klassisk regular snit med tilspidsede ben og en elastisk talje med snøre. Nem at kombinere med alt fra strik til en matchende blazer.\n\n- 65 % polyester (genanvendt), 35 % viskose\n- Regular fit med pressefolder og tilspidsede ben\n- Lynlås- og knaplukning\n- Elastisk talje med snøre\n- Side- og baglommer', E'Regular fit', E'- 100 % bomuld\r\n- Logo på brystet\r\n- Slim fit\r\n- Almindelig skuldersøm\r\n- Ribkanter\r\n- Kængurulomme\r\n- Brandlabel ved kanten'),
  (38, 'de', E'Diese Edition unserer Como-Serie kommt im klassischen regulären Schnitt mit schmal zulaufendem Bein und elastischem Tunnelzugbund. Lässt sich mit allem kombinieren, vom Strickpullover bis zum passenden Blazer.\n\n- 65 % Polyester (recycelt), 35 % Viskose\n- Reguläre Passform mit Bügelfalte und schmal zulaufendem Bein\n- Reißverschluss und Knopf\n- Elastischer Tunnelzugbund\n- Seiten- und Gesäßtaschen', E'Reguläre Passform', E'- 100 % Baumwolle\r\n- Markenschriftzug auf der Brust\r\n- Slim Fit\r\n- Normale Schulternaht\r\n- Gerippte Säume\r\n- Kängurutasche\r\n- Markenlabel am Saum'),
  (39, 'el', E'Ένα υβρίδιο πόλο και t-shirt. Φτιαγμένο από πικέ, το ύφασμα των πόλο, αυτό το t-shirt έχει άνετη στρογγυλή λαιμόκοψη και κεντημένο λογότυπο Encore στο στήθος.\n\n- 100% βαμβάκι\n- Στρογγυλή λαιμόκοψη\n- Πικέ ύφανση που αναπνέει\n- Λογότυπο Encore στο στήθος\n- Ριμπ γιακάς, μανίκια και τελείωμα\n- Στενή εφαρμογή', E'Χαλαρή εφαρμογή', E'- 100% βαμβάκι\r\n- Λογότυπο στο στήθος\r\n- Στενή εφαρμογή\r\n- Κανονική ραφή ώμου\r\n- Ριμπ τελειώματα\r\n- Τσέπη καγκουρό\r\n- Ετικέτα brand στο τελείωμα'),
  (39, 'da', E'En hybrid mellem polo og T-shirt. Lavet i piqué — materialet fra poloshirts — med en afslappet rund hals og et broderet Encore-logo på brystet.\n\n- 100 % bomuld\n- Rund hals\n- Åndbar piquévævning\n- Encore-logo på brystet\n- Ribkant ved krave, ærmer og kant\n- Slim fit', E'Løs pasform', E'- 100 % bomuld\r\n- Logo på brystet\r\n- Slim fit\r\n- Almindelig skuldersøm\r\n- Ribkanter\r\n- Kængurulomme\r\n- Brandlabel ved kanten'),
  (39, 'de', E'Ein Hybrid aus Polo und T-Shirt. Aus Piqué, dem klassischen Polo-Material, mit lässigem Rundhalsausschnitt und gesticktem Encore-Logo auf der Brust.\n\n- 100 % Baumwolle\n- Rundhalsausschnitt\n- Atmungsaktive Piqué-Struktur\n- Encore-Logo auf der Brust\n- Gerippter Kragen, Ärmel und Saum\n- Slim Fit', E'Lockere Passform', E'- 100 % Baumwolle\r\n- Markenschriftzug auf der Brust\r\n- Slim Fit\r\n- Normale Schulternaht\r\n- Gerippte Säume\r\n- Kängurutasche\r\n- Markenlabel am Saum'),
  (40, 'el', E'Το Eduard είναι ένα μεσαίου βάρους πλεκτό με μισό φερμουάρ από μαλλί merino, σε πλέξη half-cardigan για ζεστασιά και δομή.\n\n- 100% μαλλί (merino)\n- Μεσαία πλέξη\n- Όρθιος γιακάς με μισό φερμουάρ\n- Υφή πλέξης half-cardigan\n- Ριμπ μανσέτες και τελείωμα\n- Κανονική εφαρμογή', E'Κανονική εφαρμογή', E'- 100% βαμβάκι\r\n- Λογότυπο στο στήθος\r\n- Στενή εφαρμογή\r\n- Κανονική ραφή ώμου\r\n- Ριμπ τελειώματα\r\n- Τσέπη καγκουρό\r\n- Ετικέτα brand στο τελείωμα'),
  (40, 'da', E'Eduard er en mellemvægts strik med halv lynlås i merinould, strikket i halvpatent for varme og struktur.\n\n- 100 % uld (merino)\n- Mellemtyk strik\n- Høj krave med halv lynlås\n- Halvpatentstrik\n- Ribkant ved ærmer og kant\n- Regular fit', E'Regular fit', E'- 100 % bomuld\r\n- Logo på brystet\r\n- Slim fit\r\n- Almindelig skuldersøm\r\n- Ribkanter\r\n- Kængurulomme\r\n- Brandlabel ved kanten'),
  (40, 'de', E'Der Eduard ist ein mittelschwerer Troyer aus Merinowolle im Halbpatentmuster — für Wärme und Struktur.\n\n- 100 % Wolle (Merino)\n- Mittelfeiner Strick\n- Stehkragen mit halbem Reißverschluss\n- Halbpatent-Struktur\n- Gerippte Bündchen und Saum\n- Reguläre Passform', E'Reguläre Passform', E'- 100 % Baumwolle\r\n- Markenschriftzug auf der Brust\r\n- Slim Fit\r\n- Normale Schulternaht\r\n- Gerippte Säume\r\n- Kängurutasche\r\n- Markenlabel am Saum'),
  (41, 'el', E'Απαλή αίσθηση, ξεχωριστή λεπτομέρεια. Το Globe Knit έχει κανονική εφαρμογή και patchwork ζακάρ με λογότυπα και γραφικά μοτίβα, από ζεστό μείγμα μαλλιού μεσαίας πλέξης για άνεση και υφή.\n\n- 33% μαλλί, 33% πολυακρυλικό, 30% πολυεστέρας, 4% ελαστάνη\n- Μεσαία πλέξη\n- Κανονική εφαρμογή\n- Στρογγυλή λαιμόκοψη\n- Patchwork ζακάρ με γράμματα και γραφικά\n- Ριμπ γιακάς, μανσέτες και τελείωμα', E'Κανονική εφαρμογή', E'- 100% βαμβάκι\r\n- Λογότυπο στο στήθος\r\n- Στενή εφαρμογή\r\n- Κανονική ραφή ώμου\r\n- Ριμπ τελειώματα\r\n- Τσέπη καγκουρό\r\n- Ετικέτα brand στο τελείωμα'),
  (41, 'da', E'Blød fornemmelse, markante detaljer. Globe Knit har regular fit og et patchwork-jacquard af logoer og grafiske motiver i en varm, mellemtyk uldblanding for komfort og struktur.\n\n- 33 % uld, 33 % polyakryl, 30 % polyester, 4 % elastan\n- Mellemtyk strik\n- Regular fit\n- Rund hals\n- Patchwork-jacquard med bogstaver og grafik\n- Ribkant ved krave, ærmer og kant', E'Regular fit', E'- 100 % bomuld\r\n- Logo på brystet\r\n- Slim fit\r\n- Almindelig skuldersøm\r\n- Ribkanter\r\n- Kængurulomme\r\n- Brandlabel ved kanten'),
  (41, 'de', E'Weiches Gefühl, markante Details. Der Globe Knit hat eine reguläre Passform und ein Patchwork-Jacquard aus Logos und grafischen Motiven, gestrickt aus einer warmen, mittelfeinen Wollmischung für Komfort und Struktur.\n\n- 33 % Wolle, 33 % Polyacryl, 30 % Polyester, 4 % Elasthan\n- Mittelfeiner Strick\n- Reguläre Passform\n- Rundhalsausschnitt\n- Jacquard-Patchwork mit Schriftzügen und Grafiken\n- Gerippter Kragen, Bündchen und Saum', E'Reguläre Passform', E'- 100 % Baumwolle\r\n- Markenschriftzug auf der Brust\r\n- Slim Fit\r\n- Normale Schulternaht\r\n- Gerippte Säume\r\n- Kängurutasche\r\n- Markenlabel am Saum'),
  (64, 'el', E'Μαλακό πλεκτό φούτερ με κουκούλα για το κρύο', E'Χαλαρή εφαρμογή', E'Μαλακό πλεκτό ύφασμα'),
