  (121, 'el', E'Ανοιξιάτικο καπέλο για παιδιά', E'Κανονική εφαρμογή', E'Βαμβάκι που αναπνέει'),
  (121, 'da', E'Forårskasket til børn', E'Regular fit', E'Åndbar bomuld'),
  (121, 'de', E'Frühlings-Cap für Kinder', E'Reguläre Passform', E'Atmungsaktive Baumwolle')
insert into public.help_translations (help_id, locale, title, subtitle, description) values
  (11, 'el', E'ΤΕΛΩΝΕΙΟ & ΔΑΣΜΟΙ', E'Παράδοση', E'Όλες οι παραγγελίες ενδέχεται να επιβαρυνθούν με τελωνειακούς δασμούς και φόρους ανάλογα με τη χώρα σας. Τα τέλη αυτά βαρύνουν τον παραλήπτη.'),
  (11, 'da', E'TOLD & AFGIFTER', E'Levering', E'Alle ordrer kan blive pålagt told og afgifter afhængigt af dit land. Disse gebyrer betales af modtageren.'),
  (11, 'de', E'ZOLL & ABGABEN', E'Lieferung', E'Je nach Land können für alle Bestellungen Zölle und Abgaben anfallen. Diese Gebühren trägt der Empfänger.'),
  (12, 'el', E'ΑΠΟΣΤΟΛΗ EXPRESS', E'Παράδοση', E'Προσφέρουμε επιλογές αποστολής express. Οι χρόνοι παράδοσης εξαρτώνται από την τοποθεσία σας και τον τρόπο αποστολής που θα επιλέξετε.'),
  (12, 'da', E'EKSPRESLEVERING', E'Levering', E'Vi tilbyder ekspreslevering. Leveringstiden afhænger af, hvor du bor, og hvilken forsendelsesmetode du vælger.'),
  (12, 'de', E'EXPRESSVERSAND', E'Lieferung', E'Wir bieten Expressversand an. Die Lieferzeit hängt von deinem Standort und der gewählten Versandart ab.'),
  (13, 'el', E'ΠΟΙΟΙ ΕΙΝΑΙ ΟΙ ΤΡΟΠΟΙ ΑΠΟΣΤΟΛΗΣ;', E'Παραγγελία & πληρωμή', E'Προσφέρουμε κανονική και express αποστολή. Οι τρόποι αποστολής εμφανίζονται στο ταμείο.'),
  (13, 'da', E'HVILKE LEVERINGSMETODER TILBYDER I?', E'Bestilling & betaling', E'Vi tilbyder standard- og ekspreslevering. Forsendelsesmetoderne vises ved kassen.'),
  (13, 'de', E'WELCHE VERSANDARTEN GIBT ES?', E'Bestellung & Zahlung', E'Wir bieten Standard- und Expressversand an. Die Versandarten werden an der Kasse angezeigt.'),
  (14, 'el', E'ΠΩΣ ΑΛΛΑΖΩ Ή ΑΚΥΡΩΝΩ ΤΗΝ ΠΑΡΑΓΓΕΛΙΑ ΜΟΥ;', E'Παραγγελία & πληρωμή', E'Μπορείτε να αλλάξετε ή να ακυρώσετε την παραγγελία σας εντός 1 ώρας από την καταχώρησή της, επικοινωνώντας με την υποστήριξη.'),
  (14, 'da', E'HVORDAN ÆNDRER ELLER ANNULLERER JEG MIN ORDRE?', E'Bestilling & betaling', E'Du kan ændre eller annullere din ordre inden for 1 time efter bestillingen ved at kontakte vores support.'),
  (14, 'de', E'WIE ÄNDERE ODER STORNIERE ICH MEINE BESTELLUNG?', E'Bestellung & Zahlung', E'Du kannst deine Bestellung innerhalb von 1 Stunde nach Aufgabe ändern oder stornieren, indem du unseren Support kontaktierst.'),
  (15, 'el', E'ΠΟΥ ΕΙΝΑΙ Η ΠΑΡΑΓΓΕΛΙΑ ΜΟΥ;', E'Παραγγελία & πληρωμή', E'Θα λάβετε αριθμό αποστολής μόλις αποσταλεί η παραγγελία σας. Χρησιμοποιήστε τον για να παρακολουθείτε το δέμα σας online.'),
  (15, 'da', E'HVOR ER MIN ORDRE?', E'Bestilling & betaling', E'Du modtager et trackingnummer, når din ordre er afsendt. Brug det til at følge din pakke online.'),
  (15, 'de', E'WO IST MEINE BESTELLUNG?', E'Bestellung & Zahlung', E'Sobald deine Bestellung versendet wurde, erhältst du eine Sendungsnummer, mit der du dein Paket online verfolgen kannst.'),
  (16, 'el', E'ΤΡΟΠΟΙ ΠΛΗΡΩΜΗΣ', E'Παραγγελία & πληρωμή', E'Δεχόμαστε τις κυριότερες πιστωτικές κάρτες, PayPal και άλλους τρόπους πληρωμής που εμφανίζονται στο ταμείο.'),
  (16, 'da', E'BETALINGSMETODER', E'Bestilling & betaling', E'Vi modtager de mest gængse kreditkort, PayPal og andre betalingsmetoder, som vises ved kassen.'),
  (16, 'de', E'ZAHLUNGSARTEN', E'Bestellung & Zahlung', E'Wir akzeptieren alle gängigen Kreditkarten, PayPal und weitere Zahlungsarten, die an der Kasse angezeigt werden.'),
  (17, 'el', E'ΠΩΣ ΕΠΙΣΤΡΕΦΩ ΤΗΝ ΠΑΡΑΓΓΕΛΙΑ ΜΟΥ;', E'Επιστροφές, αποζημιώσεις & παράπονα', E'Μπορείτε να επιστρέψετε προϊόντα εντός 30 ημερών από την παράδοση, στην αρχική τους κατάσταση και με τις ετικέτες τους.'),
  (17, 'da', E'HVORDAN RETURNERER JEG MIN ORDRE?', E'Returnering, refusion & reklamationer', E'Du kan returnere varer inden for 30 dage efter levering i original stand og med mærkerne på.'),
  (17, 'de', E'WIE SENDE ICH MEINE BESTELLUNG ZURÜCK?', E'Rücksendungen, Erstattungen & Reklamationen', E'Du kannst Artikel innerhalb von 30 Tagen nach Lieferung im Originalzustand und mit Etiketten zurücksenden.'),
  (18, 'el', E'ΠΩΣ ΑΝΤΑΛΛΑΣΣΩ ΤΗΝ ΠΑΡΑΓΓΕΛΙΑ ΜΟΥ;', E'Επιστροφές, αποζημιώσεις & παράπονα', E'Οι ανταλλαγές γίνονται επιστρέφοντας το προϊόν και κάνοντας νέα παραγγελία για το προϊόν που θέλετε.'),
  (18, 'da', E'HVORDAN BYTTER JEG MIN ORDRE?', E'Returnering, refusion & reklamationer', E'Ombytning foregår ved, at du returnerer varen og afgiver en ny ordre på den ønskede vare.'),
  (18, 'de', E'WIE TAUSCHE ICH MEINE BESTELLUNG UM?', E'Rücksendungen, Erstattungen & Reklamationen', E'Für einen Umtausch sendest du den Artikel zurück und gibst eine neue Bestellung für den gewünschten Artikel auf.'),
  (19, 'el', E'ΠΟΤΕ ΘΑ ΛΑΒΩ ΤΗΝ ΕΠΙΣΤΡΟΦΗ ΧΡΗΜΑΤΩΝ;', E'Επιστροφές, αποζημιώσεις & παράπονα', E'Οι επιστροφές χρημάτων διεκπεραιώνονται εντός 5-7 εργάσιμων ημερών από τη στιγμή που θα παραλάβουμε τα προϊόντα.'),
  (19, 'da', E'HVORNÅR FÅR JEG MINE PENGE TILBAGE?', E'Returnering, refusion & reklamationer', E'Refusioner behandles inden for 5-7 hverdage, efter vi har modtaget dine returnerede varer.'),
  (19, 'de', E'WANN ERHALTE ICH MEINE ERSTATTUNG?', E'Rücksendungen, Erstattungen & Reklamationen', E'Erstattungen werden innerhalb von 5-7 Werktagen nach Eingang deiner Rücksendung bearbeitet.'),
  (20, 'el', E'ΤΙ ΚΑΝΩ ΑΝ ΤΟ ΠΡΟΪΟΝ ΕΙΝΑΙ ΕΛΑΤΤΩΜΑΤΙΚΟ;', E'Επιστροφές, αποζημιώσεις & παράπονα', E'Αν το προϊόν σας είναι ελαττωματικό, επικοινωνήστε αμέσως με την υποστήριξη για αντικατάσταση ή επιστροφή χρημάτων.'),
  (20, 'da', E'HVAD GØR JEG, HVIS MIN VARE ER DEFEKT?', E'Returnering, refusion & reklamationer', E'Hvis din vare er defekt, så kontakt vores support med det samme for at få en ny vare eller pengene tilbage.'),
  (20, 'de', E'WAS TUE ICH, WENN MEIN ARTIKEL FEHLERHAFT IST?', E'Rücksendungen, Erstattungen & Reklamationen', E'Wenn dein Artikel fehlerhaft ist, kontaktiere bitte umgehend unseren Support für Ersatz oder Erstattung.'),
  (21, 'el', E'ΠΩΣ ΑΓΟΡΑΖΩ ΔΩΡΟΚΑΡΤΑ;', E'Δωροκάρτα', E'Μπορείτε να αγοράσετε δωροκάρτα από την ιστοσελίδα μας. Οι δωροκάρτες αποστέλλονται ψηφιακά μέσω email.'),
  (21, 'da', E'HVORDAN KØBER JEG ET GAVEKORT?', E'Gavekort', E'Du kan købe et gavekort på vores hjemmeside. Gavekort leveres digitalt via e-mail.'),
  (21, 'de', E'WIE KAUFE ICH EINE GESCHENKKARTE?', E'Geschenkkarte', E'Du kannst eine Geschenkkarte auf unserer Website kaufen. Geschenkkarten werden digital per E-Mail zugestellt.'),
  (22, 'el', E'ΠΟΣΟ ΔΙΑΡΚΕΙ ΜΙΑ ΔΩΡΟΚΑΡΤΑ;', E'Δωροκάρτα', E'Οι δωροκάρτες ισχύουν για 12 μήνες από την ημερομηνία έκδοσης.'),
  (22, 'da', E'HVOR LÆNGE GÆLDER ET GAVEKORT?', E'Gavekort', E'Gavekort er gyldige i 12 måneder fra udstedelsesdatoen.'),
  (22, 'de', E'WIE LANGE IST EINE GESCHENKKARTE GÜLTIG?', E'Geschenkkarte', E'Geschenkkarten sind 12 Monate ab Ausstellungsdatum gültig.'),
  (23, 'el', E'ΠΩΣ ΕΠΙΣΤΡΕΦΩ ΜΙΑ ΑΓΟΡΑ ΠΟΥ ΕΚΑΝΑ ΜΕ ΔΩΡΟΚΑΡΤΑ;', E'Δωροκάρτα', E'Οι αγορές που έγιναν με δωροκάρτα επιστρέφονται σύμφωνα με την κανονική πολιτική επιστροφών μας.'),
  (23, 'da', E'HVORDAN RETURNERER JEG ET KØB BETALT MED GAVEKORT?', E'Gavekort', E'Køb betalt med gavekort kan returneres efter vores almindelige returpolitik.'),
  (23, 'de', E'WIE SENDE ICH EINEN MIT GESCHENKKARTE BEZAHLTEN KAUF ZURÜCK?', E'Geschenkkarte', E'Mit einer Geschenkkarte bezahlte Käufe können gemäß unseren regulären Rückgabebedingungen zurückgegeben werden.'),
  (24, 'el', E'ΠΩΣ ΕΛΕΓΧΩ ΤΟ ΥΠΟΛΟΙΠΟ ΜΟΥ;', E'Δωροκάρτα', E'Μπορείτε να ελέγξετε το υπόλοιπο της δωροκάρτας σας στην ιστοσελίδα μας με τον κωδικό της.'),
  (24, 'da', E'HVORDAN TJEKKER JEG MIN SALDO?', E'Gavekort', E'Du kan tjekke saldoen på dit gavekort på vores hjemmeside med gavekortkoden.'),
  (24, 'de', E'WIE PRÜFE ICH MEIN GUTHABEN?', E'Geschenkkarte', E'Du kannst das Guthaben deiner Geschenkkarte mit dem Geschenkkartencode auf unserer Website prüfen.'),
  (25, 'el', E'ΔΕΝ ΒΡΗΚΑΤΕ ΑΥΤΟ ΠΟΥ ΨΑΧΝΑΤΕ;', E'Επικοινωνία', E'Αν δεν βρήκατε την πληροφορία που ψάχνατε, επικοινωνήστε με την ομάδα υποστήριξης μέσω email ή chat.'),
  (25, 'da', E'FANDT DU IKKE DET, DU LEDTE EFTER?', E'Kontakt', E'Hvis du ikke fandt de oplysninger, du ledte efter, så kontakt vores supportteam via e-mail eller chat.'),
  (25, 'de', E'NICHT GEFUNDEN, WONACH DU GESUCHT HAST?', E'Kontakt', E'Wenn du die gesuchten Informationen nicht gefunden hast, kontaktiere unser Support-Team per E-Mail oder Chat.')
insert into public.page_translations (page_id, locale, title, content) values
  ('ea6e1b92-5b4e-4e3d-b96d-9e1f79daa90f', 'el', E'Πολιτική απορρήτου', E'<h2>1. Εισαγωγή</h2>\n<p>Όταν χρησιμοποιείτε την ιστοσελίδα και τις υπηρεσίες μας, εγγράφεστε στο newsletter μας, εγγράφεστε ως «μέλος», αγοράζετε προϊόντα από την ιστοσελίδα μας ή επισκέπτεστε ένα από τα καταστήματά μας, η Methys (στο εξής «Methys», «εμείς» ή «μας») επεξεργάζεται τα δεδομένα σας όπως περιγράφεται στην παρούσα πολιτική απορρήτου.</p>\n\n<h2>2. Υπεύθυνος επεξεργασίας</h2>\n<p>Η Methys είναι ο υπεύθυνος επεξεργασίας για την επεξεργασία προσωπικών δεδομένων σύμφωνα με τις παρακάτω ενότητες. Αν θέλετε να επικοινωνήσετε μαζί μας, τα στοιχεία επικοινωνίας μας είναι:</p>\n<p>Methys<br/>Δασκαλογιάννη 33<br/>73100 Χανιά, Κρήτη, Ελλάδα<br/>E-mail: support@methys.com</p>\n\n<h2>3. Επεξεργασία προσωπικών δεδομένων</h2>\n<p>Επεξεργαζόμαστε τα προσωπικά σας δεδομένα όταν επισκέπτεστε την ιστοσελίδα μας ή ένα από τα καταστήματά μας.</p>\n\n<h3>3.1 Χρήση της ιστοσελίδας χωρίς εγγραφή σε υπηρεσίες</h3>\n<p>Μπορείτε να χρησιμοποιήσετε την ιστοσελίδα μας χωρίς να συλλέξουμε προσωπικά σας δεδομένα. Ωστόσο, λάβετε υπόψη ότι κατά τη χρήση της ιστοσελίδας ενδέχεται να χρησιμοποιούμε cookies, και η απενεργοποίησή τους μπορεί να περιορίσει τη λειτουργικότητα της ιστοσελίδας. Αποδεχόμενοι τα cookies, επεξεργαζόμαστε τα προσωπικά δεδομένα για τα οποία έχετε δώσει τη συγκατάθεσή σας, όπως τη διεύθυνση IP σας, πληροφορίες για τον browser σας, ποια μέρη της ιστοσελίδας επισκέπτεστε και για πόσο χρόνο.</p>\n\n<h3>3.2 Εγγραφή σε υπηρεσίες και αγορές από την ιστοσελίδα</h3>\n<p>Επεξεργαζόμαστε τα προσωπικά σας δεδομένα όταν σας παρέχουμε ή βελτιώνουμε τις υπηρεσίες μας, για παράδειγμα όταν εγγράφεστε στις υπηρεσίες μας, αποδέχεστε cookies, επικοινωνείτε μαζί μας ή πραγματοποιείτε μια αγορά.</p>\n\n<h4>3.2.1 Παραγγελίες</h4>\n<p>Η Methys επεξεργάζεται τις ακόλουθες πληροφορίες όταν πραγματοποιείτε αγορά από την ιστοσελίδα:</p>\n<ul>\n  <li>Όνομα</li>\n  <li>Διεύθυνση</li>\n  <li>E-mail</li>\n  <li>Αριθμός τηλεφώνου</li>\n  <li>Χώρα</li>\n  <li>Στοιχεία πληρωμής</li>\n  <li>Στοιχεία σύνδεσης & κωδικός πρόσβασης</li>\n  <li>Διεύθυνση/-εις IP</li>\n  <li>Πληροφορίες παραγγελίας</li>\n</ul>\n<p>Ο σκοπός της επεξεργασίας είναι:</p>\n<ul>\n  <li>Η διαχείριση της σχέσης σας μαζί μας</li>\n  <li>Η παράδοση της παραγγελίας σας</li>\n  <li>Η βελτίωση των υπηρεσιών μας</li>\n  <li>Η προσαρμογή της επικοινωνίας και του μάρκετινγκ προς εσάς</li>\n</ul>\n<p><strong>Νομική βάση:</strong> Επεξεργαζόμαστε τα δεδομένα σας για την εκτέλεση της σύμβασής μας μαζί σας (άρθρο 6 παρ. 1 στοιχ. β΄ ΓΚΠΔ). Εφόσον έχετε δώσει τη συγκατάθεσή σας, επεξεργαζόμαστε τις πληροφορίες σας για να σας στέλνουμε περιεχόμενο μάρκετινγκ (άρθρο 6 παρ. 1 στοιχ. α΄ ΓΚΠΔ). Επεξεργαζόμαστε επίσης τα δεδομένα σας λόγω του έννομου συμφέροντός μας να προσαρμόζουμε την επικοινωνία και το μάρκετινγκ προς εσάς (άρθρο 6 παρ. 1 στοιχ. στ΄ ΓΚΠΔ).</p>\n<p>Όταν πραγματοποιείτε αγορά από την ιστοσελίδα μας, κοινοποιούμε τα δεδομένα σας στους ακόλουθους τρίτους:</p>\n<ul>\n  <li>Εταιρείες logistics για την παράδοση της παραγγελίας σας</li>\n  <li>Την Trustpilot, ώστε να μπορεί να επικοινωνήσει μαζί σας μέσω e-mail σχετικά με την εμπειρία αγοράς σας</li>\n  <li>Εταιρείες μέσων κοινωνικής δικτύωσης ή παρόμοιους τρίτους με τους οποίους συνεργαζόμαστε για μάρκετινγκ και διαφήμιση</li>\n</ul>\n\n<h4>3.2.2 Εγγραφή ως «μέλος»</h4>\n<p>Η Methys επεξεργάζεται τις ακόλουθες πληροφορίες όταν εγγράφεστε ως «μέλος» στην ιστοσελίδα μας:</p>\n<ul>\n  <li>Όνομα</li>\n  <li>Διεύθυνση</li>\n  <li>E-mail</li>\n  <li>Πληροφορίες για τις παραγγελίες σας</li>\n  <li>Άλλες πληροφορίες που επιλέγετε να μας δώσετε</li>\n</ul>\n<p>Ο σκοπός της επεξεργασίας είναι:</p>\n<ul>\n  <li>Η παροχή περιβάλλοντος με επισκόπηση των παραγγελιών σας</li>\n  <li>Η διασφάλιση μιας αποτελεσματικής διαδικασίας αγοράς</li>\n  <li>Η προσαρμογή της επικοινωνίας και του μάρκετινγκ προς εσάς</li>\n</ul>\n<p><strong>Νομική βάση:</strong> Επεξεργαζόμαστε τα δεδομένα σας λόγω του έννομου συμφέροντός μας να παρέχουμε και να διαχειριζόμαστε το προφίλ «μέλους» σας και να προσαρμόζουμε την επικοινωνία και το μάρκετινγκ προς εσάς (άρθρο 6 παρ. 1 στοιχ. στ΄ ΓΚΠΔ).</p>\n\n<h4>3.2.3 Newsletter και επικοινωνία</h4>\n<p>Η Methys επεξεργάζεται τις ακόλουθες πληροφορίες όταν εγγράφεστε στο newsletter μας ή επικοινωνείτε μαζί μας:</p>\n<ul>\n  <li>Όνομα</li>\n  <li>E-mail</li>\n  <li>Άλλα στοιχεία επικοινωνίας ή πληροφορίες που επιλέγετε να μας δώσετε</li>\n  <li>Συμπεριφορά στην ιστοσελίδα και ιστορικό δραστηριότητας</li>\n</ul>\n<p>Ο σκοπός της επεξεργασίας είναι:</p>\n<ul>\n  <li>Η αποστολή newsletter</li>\n  <li>Η απάντηση στο αίτημά σας</li>\n  <li>Η προσαρμογή της επικοινωνίας και του μάρκετινγκ προς εσάς</li>\n</ul>\n<p><strong>Νομική βάση:</strong> Αφού λάβουμε τη συγκατάθεσή σας για την αποστολή newsletter, επεξεργαζόμαστε τα δεδομένα σας λόγω του έννομου συμφέροντός μας να αποστέλλουμε το newsletter (άρθρο 6 παρ. 1 στοιχ. στ΄ ΓΚΠΔ). Αν επικοινωνήσετε μαζί μας, επεξεργαζόμαστε τις πληροφορίες σας λόγω του έννομου συμφέροντός μας να απαντήσουμε στο αίτημά σας (άρθρο 6 παρ. 1 στοιχ. στ΄ ΓΚΠΔ).</p>\n\n<h2>4. Εκτελούντες την επεξεργασία και διαβίβαση προσωπικών δεδομένων</h2>\n<p>Τα προσωπικά σας δεδομένα μπορεί να κοινοποιούνται σε πωλητές, προμηθευτές ή άλλους τρίτους που επεξεργάζονται δεδομένα για λογαριασμό της Methys (εκτελούντες την επεξεργασία). Όταν συνεργάζεται με τέτοιους εκτελούντες την επεξεργασία, η Methys υπογράφει συμβάσεις επεξεργασίας δεδομένων που τους δεσμεύουν σε εμπιστευτικότητα και σε επεξεργασία των προσωπικών δεδομένων μόνο σύμφωνα με τις οδηγίες της Methys. Διαβιβάζουμε δεδομένα σε χώρες εκτός ΕΟΧ μόνο όταν υπάρχουν οι κατάλληλες εγγυήσεις που προβλέπει ο ΓΚΠΔ.</p>\n\n<h2>5. Χρόνος διατήρησης</h2>\n<p>Διαγράφουμε τα δεδομένα σας όταν δεν είναι πλέον απαραίτητο να τα διατηρούμε για τους σκοπούς που περιγράφονται στην παρούσα πολιτική απορρήτου. Ορισμένα είδη πληροφοριών τα διατηρούμε για μεγαλύτερο διάστημα, εφόσον υποχρεούμαστε από τον νόμο. Διαγράφουμε ανενεργά προφίλ «μελών» μετά από ένα έτος αδράνειας και ενημερώνουμε τον χρήστη πριν το κάνουμε.</p>\n\n<h2>6. Τα δικαιώματά σας</h2>\n<p>Έχετε το δικαίωμα να μας ζητήσετε επιβεβαίωση για το αν επεξεργαζόμαστε τα δεδομένα σας και να ζητήσετε πρόσβαση σε αυτά. Έχετε το δικαίωμα να μας ζητήσετε διόρθωση, διαγραφή ή περιορισμό της επεξεργασίας των πληροφοριών σας, καθώς και να αντιταχθείτε στην επεξεργασία. Επιπλέον, έχετε δικαίωμα στη φορητότητα των δεδομένων.</p>\n<p>Εφόσον επεξεργαζόμαστε τα δεδομένα σας βάσει της συγκατάθεσής σας, έχετε το δικαίωμα να την ανακαλέσετε ανά πάσα στιγμή.</p>\n<p>Αν θέλετε να ασκήσετε τα δικαιώματά σας ή έχετε ερωτήσεις σχετικά με την παρούσα πολιτική, επικοινωνήστε μαζί μας στο <strong>support@methys.com</strong> ή ταχυδρομικά στη διεύθυνση Methys, Δασκαλογιάννη 33, 73100 Χανιά, Κρήτη, Ελλάδα.</p>'),
  ('ea6e1b92-5b4e-4e3d-b96d-9e1f79daa90f', 'da', E'Privatlivspolitik', E'<h2>1. Indledning</h2>\n<p>Når du bruger hjemmesiden og vores tjenester, tilmelder dig vores nyhedsbrev, opretter dig som „medlem“, køber varer på vores hjemmeside eller besøger en af vores butikker, behandler Methys (herefter „Methys“, „vi“ eller „vores“) dine data som beskrevet i denne privatlivspolitik.</p>\n\n<h2>2. Dataansvar</h2>\n<p>Methys er dataansvarlig for behandlingen af personoplysninger som beskrevet i afsnittene nedenfor. Hvis du vil i kontakt med os, er vores kontaktoplysninger:</p>\n<p>Methys<br/>Daskalogianni 33<br/>73100 Chania, Kreta, Grækenland<br/>E-mail: support@methys.com</p>\n\n<h2>3. Behandling af personoplysninger</h2>\n<p>Vi behandler dine personoplysninger, når du besøger vores hjemmeside eller en af vores butikker.</p>\n\n<h3>3.1 Brug af hjemmesiden uden tilmelding til tjenester</h3>\n<p>Det er muligt at bruge vores hjemmeside, uden at vi indsamler dine personoplysninger. Vær dog opmærksom på, at vi kan bruge cookies, når du bruger hjemmesiden, og at deaktivering af cookies kan begrænse hjemmesidens funktionalitet. Når du accepterer cookies, behandler vi de personoplysninger, du har givet samtykke til, såsom din IP-adresse, oplysninger om din browser, hvilke dele af hjemmesiden du besøger, og hvor længe.</p>\n\n<h3>3.2 Tilmelding til tjenester og køb på hjemmesiden</h3>\n<p>Vi behandler dine personoplysninger, når vi leverer eller forbedrer vores tjenester til dig, f.eks. når du tilmelder dig vores tjenester, accepterer cookies, kontakter os eller foretager et køb.</p>\n\n<h4>3.2.1 Ordrer</h4>\n<p>Methys behandler følgende oplysninger, når du foretager et køb på hjemmesiden:</p>\n<ul>\n  <li>Navn</li>\n  <li>Adresse</li>\n  <li>E-mail</li>\n  <li>Telefonnummer</li>\n  <li>Land</li>\n  <li>Betalingsoplysninger</li>\n  <li>Login & adgangskode</li>\n  <li>IP-adresse(r)</li>\n  <li>Ordreoplysninger</li>\n</ul>\n<p>Formålet med behandlingen er:</p>\n<ul>\n  <li>Administration af dit forhold til os</li>\n  <li>Levering af din ordre</li>\n  <li>Forbedring af vores tjenester</li>\n  <li>Tilpasning af vores kommunikation og markedsføring til dig</li>\n</ul>\n<p><strong>Retsgrundlag:</strong> Vi behandler dine data for at opfylde vores aftale med dig (artikel 6, stk. 1, litra b, i GDPR). Hvis du har givet samtykke, behandler vi dine oplysninger for at sende dig markedsføringsindhold (artikel 6, stk. 1, litra a, i GDPR). Vi behandler også dine data på grund af vores legitime interesse i at tilpasse vores kommunikation og markedsføring til dig (artikel 6, stk. 1, litra f, i GDPR).</p>\n<p>Når du handler på vores hjemmeside, deler vi dine data med følgende tredjeparter:</p>\n<ul>\n  <li>Logistikvirksomheder, der leverer din ordre</li>\n  <li>Trustpilot, så de kan kontakte dig via e-mail om din købsoplevelse</li>\n  <li>Sociale medier eller lignende tredjeparter, som vi samarbejder med om markedsføring og annoncering</li>\n</ul>\n\n<h4>3.2.2 Tilmelding som „medlem“</h4>\n<p>Methys behandler følgende oplysninger, når du tilmelder dig som „medlem“ på vores hjemmeside:</p>\n<ul>\n  <li>Navn</li>\n  <li>Adresse</li>\n  <li>E-mail</li>\n  <li>Oplysninger om afgivne ordrer</li>\n  <li>Andre oplysninger, som du vælger at give os</li>\n</ul>\n<p>Formålet med behandlingen er:</p>\n<ul>\n  <li>At give dig en oversigt over dine afgivne ordrer</li>\n  <li>At sikre en effektiv købsproces</li>\n  <li>At tilpasse vores kommunikation og markedsføring til dig</li>\n</ul>\n<p><strong>Retsgrundlag:</strong> Vi behandler dine data på grund af vores legitime interesse i at levere og administrere din „medlemsprofil“ og tilpasse vores kommunikation og markedsføring til dig (artikel 6, stk. 1, litra f, i GDPR).</p>\n\n<h4>3.2.3 Nyhedsbrev og kontakt</h4>\n<p>Methys behandler følgende oplysninger, når du tilmelder dig vores nyhedsbrev eller kontakter os:</p>\n<ul>\n  <li>Navn</li>\n  <li>E-mail</li>\n  <li>Andre kontaktoplysninger eller informationer, som du vælger at give os</li>\n  <li>Adfærd på hjemmesiden og historisk aktivitet</li>\n</ul>\n<p>Formålet med behandlingen er:</p>\n<ul>\n  <li>At sende dig nyhedsbreve</li>\n  <li>At besvare din henvendelse</li>\n  <li>At tilpasse vores kommunikation og markedsføring til dig</li>\n</ul>\n<p><strong>Retsgrundlag:</strong> Når vi har fået dit samtykke til at modtage nyhedsbreve, behandler vi dine data på grund af vores legitime interesse i at sende nyhedsbrevet (artikel 6, stk. 1, litra f, i GDPR). Hvis du kontakter os, behandler vi dine oplysninger på grund af vores legitime interesse i at besvare din henvendelse (artikel 6, stk. 1, litra f, i GDPR).</p>\n\n<h2>4. Databehandlere og overførsel af personoplysninger</h2>\n<p>Dine personoplysninger kan blive delt med leverandører eller andre tredjeparter, der behandler data på vegne af Methys (databehandlere). Når Methys benytter sådanne databehandlere, indgår vi databehandleraftaler, der forpligter dem til fortrolighed og til kun at behandle personoplysninger efter Methys\' instruks. Vi overfører kun data til lande uden for EØS, når de nødvendige garantier i henhold til GDPR er på plads.</p>\n\n<h2>5. Opbevaringsperioder</h2>\n<p>Vi sletter dine data, når det ikke længere er nødvendigt at opbevare dem til de formål, der er beskrevet i denne privatlivspolitik. Visse typer oplysninger opbevarer vi længere, hvis vi er forpligtet til det ved lov. Vi sletter inaktive „medlemsprofiler“ efter et års inaktivitet og giver brugeren besked, inden det sker.</p>\n\n<h2>6. Dine rettigheder</h2>\n<p>Du har ret til at bede os bekræfte, om vi behandler dine data, og til at få indsigt i dem. Du har ret til at bede os berigtige, slette eller begrænse behandlingen af dine oplysninger og til at gøre indsigelse mod vores behandling. Desuden har du ret til dataportabilitet.</p>\n<p>Hvis vi behandler dine data på baggrund af dit samtykke, har du til enhver tid ret til at trække dit samtykke tilbage.</p>\n<p>Hvis du vil udøve dine rettigheder eller har spørgsmål til denne politik, så kontakt os på <strong>support@methys.com</strong> eller med post til Methys, Daskalogianni 33, 73100 Chania, Kreta, Grækenland.</p>'),
  ('ea6e1b92-5b4e-4e3d-b96d-9e1f79daa90f', 'de', E'Datenschutzerklärung', E'<h2>1. Einleitung</h2>\n<p>Wenn du unsere Website und unsere Dienste nutzt, unseren Newsletter abonnierst, dich als „Mitglied“ registrierst, Waren auf unserer Website kaufst oder eines unserer Geschäfte besuchst, verarbeitet Methys (im Folgenden „Methys“, „wir“ oder „uns“) deine Daten wie in dieser Datenschutzerklärung beschrieben.</p>\n\n<h2>2. Verantwortlicher</h2>\n<p>Methys ist Verantwortlicher für die Verarbeitung personenbezogener Daten gemäß den folgenden Abschnitten. Wenn du mit uns in Kontakt treten möchtest, lauten unsere Kontaktdaten:</p>\n<p>Methys<br/>Daskalogianni 33<br/>73100 Chania, Kreta, Griechenland<br/>E-Mail: support@methys.com</p>\n\n<h2>3. Verarbeitung personenbezogener Daten</h2>\n<p>Wir verarbeiten deine personenbezogenen Daten, wenn du unsere Website oder eines unserer Geschäfte besuchst.</p>\n\n<h3>3.1 Nutzung unserer Website ohne Anmeldung zu Diensten</h3>\n<p>Du kannst unsere Website nutzen, ohne dass wir personenbezogene Daten von dir erheben. Bitte beachte jedoch, dass wir bei der Nutzung der Website Cookies verwenden können und dass die Deaktivierung von Cookies die Funktionalität unserer Website einschränken kann. Wenn du Cookies akzeptierst, verarbeiten wir die personenbezogenen Daten, in deren Verarbeitung du eingewilligt hast, etwa deine IP-Adresse, Informationen zu deinem Browser sowie welche Bereiche unserer Website du wie lange besuchst.</p>\n\n<h3>3.2 Anmeldung zu Diensten und Einkäufe auf der Website</h3>\n<p>Wir verarbeiten deine personenbezogenen Daten, wenn wir unsere Dienste für dich erbringen oder verbessern, z. B. wenn du dich für unsere Dienste anmeldest, Cookies akzeptierst, uns kontaktierst oder einen Kauf tätigst.</p>\n\n<h4>3.2.1 Bestellungen</h4>\n<p>Methys verarbeitet die folgenden Informationen, wenn du einen Kauf auf der Website tätigst:</p>\n<ul>\n  <li>Name</li>\n  <li>Adresse</li>\n  <li>E-Mail</li>\n  <li>Telefonnummer</li>\n  <li>Land</li>\n  <li>Zahlungsinformationen</li>\n  <li>Login & Passwort</li>\n  <li>IP-Adresse(n)</li>\n  <li>Bestellinformationen</li>\n</ul>\n<p>Zweck der Verarbeitung ist:</p>\n<ul>\n  <li>Die Verwaltung deiner Beziehung zu uns</li>\n  <li>Die Lieferung deiner Bestellung</li>\n  <li>Die Verbesserung unserer Dienste</li>\n  <li>Die Anpassung unserer Kommunikation und unseres Marketings an dich</li>\n</ul>\n<p><strong>Rechtsgrundlage:</strong> Wir verarbeiten deine Daten zur Erfüllung unseres Vertrags mit dir (Art. 6 Abs. 1 lit. b DSGVO). Wenn du eingewilligt hast, verarbeiten wir deine Informationen, um dir Marketinginhalte zuzusenden (Art. 6 Abs. 1 lit. a DSGVO). Außerdem verarbeiten wir deine Daten aufgrund unseres berechtigten Interesses, unsere Kommunikation und unser Marketing an dich anzupassen (Art. 6 Abs. 1 lit. f DSGVO).</p>\n<p>Wenn du auf unserer Website einkaufst, geben wir deine Daten an folgende Dritte weiter:</p>\n<ul>\n  <li>Logistikunternehmen zur Lieferung deiner Bestellung</li>\n  <li>Trustpilot, damit dich Trustpilot per E-Mail zu deinem Einkaufserlebnis kontaktieren kann</li>\n  <li>Social-Media-Unternehmen oder vergleichbare Dritte, mit denen wir für Marketing und Werbung zusammenarbeiten</li>\n</ul>\n\n<h4>3.2.2 Registrierung als „Mitglied“</h4>\n<p>Methys verarbeitet die folgenden Informationen, wenn du dich als „Mitglied“ auf unserer Website registrierst:</p>\n<ul>\n  <li>Name</li>\n  <li>Adresse</li>\n  <li>E-Mail</li>\n  <li>Informationen zu aufgegebenen Bestellungen</li>\n  <li>Weitere Informationen, die du uns freiwillig mitteilst</li>\n</ul>\n<p>Zweck der Verarbeitung ist:</p>\n<ul>\n  <li>Die Bereitstellung einer Übersicht über deine Bestellungen</li>\n  <li>Ein effizienter Kaufprozess</li>\n  <li>Die Anpassung unserer Kommunikation und unseres Marketings an dich</li>\n</ul>\n<p><strong>Rechtsgrundlage:</strong> Wir verarbeiten deine Daten aufgrund unseres berechtigten Interesses, dein „Mitgliedsprofil“ bereitzustellen und zu verwalten und unsere Kommunikation und unser Marketing an dich anzupassen (Art. 6 Abs. 1 lit. f DSGVO).</p>\n\n<h4>3.2.3 Newsletter und Kontakt</h4>\n<p>Methys verarbeitet die folgenden Informationen, wenn du unseren Newsletter abonnierst oder uns kontaktierst:</p>\n<ul>\n  <li>Name</li>\n  <li>E-Mail</li>\n  <li>Weitere Kontaktdaten oder Informationen, die du uns freiwillig mitteilst</li>\n  <li>Nutzungsverhalten auf der Website und bisherige Aktivitäten</li>\n</ul>\n<p>Zweck der Verarbeitung ist:</p>\n<ul>\n  <li>Der Versand von Newslettern</li>\n  <li>Die Beantwortung deiner Anfrage</li>\n  <li>Die Anpassung unserer Kommunikation und unseres Marketings an dich</li>\n</ul>\n<p><strong>Rechtsgrundlage:</strong> Nachdem wir deine Einwilligung zum Erhalt von Newslettern eingeholt haben, verarbeiten wir deine Daten aufgrund unseres berechtigten Interesses am Versand des Newsletters (Art. 6 Abs. 1 lit. f DSGVO). Wenn du uns kontaktierst, verarbeiten wir deine Informationen aufgrund unseres berechtigten Interesses, deine Anfrage zu beantworten (Art. 6 Abs. 1 lit. f DSGVO).</p>\n\n<h2>4. Auftragsverarbeiter und Übermittlung personenbezogener Daten</h2>\n<p>Deine personenbezogenen Daten können an Anbieter, Lieferanten oder andere Dritte weitergegeben werden, die Daten im Auftrag von Methys verarbeiten (Auftragsverarbeiter). Beim Einsatz solcher Auftragsverarbeiter schließt Methys Auftragsverarbeitungsverträge ab, die diese zur Vertraulichkeit verpflichten und dazu, personenbezogene Daten ausschließlich nach den Weisungen von Methys zu verarbeiten. Wir übermitteln Daten nur dann in Länder außerhalb des EWR, wenn geeignete Garantien gemäß DSGVO bestehen.</p>\n\n<h2>5. Speicherdauer</h2>\n<p>Wir löschen deine Daten, sobald ihre Speicherung für die in dieser Datenschutzerklärung genannten Zwecke nicht mehr erforderlich ist. Bestimmte Informationen speichern wir länger, wenn wir gesetzlich dazu verpflichtet sind. Inaktive „Mitgliedsprofile“ löschen wir nach einem Jahr Inaktivität und benachrichtigen den Nutzer vorher.</p>\n\n<h2>6. Deine Rechte</h2>\n<p>Du hast das Recht, von uns eine Bestätigung darüber zu verlangen, ob wir deine Daten verarbeiten, und Auskunft über diese Daten zu erhalten. Du hast das Recht, die Berichtigung, Löschung oder Einschränkung der Verarbeitung deiner Informationen zu verlangen und der Verarbeitung zu widersprechen. Außerdem hast du das Recht auf Datenübertragbarkeit.</p>\n<p>Wenn wir deine Daten auf Grundlage deiner Einwilligung verarbeiten, hast du das Recht, diese Einwilligung jederzeit zu widerrufen.</p>\n<p>Wenn du deine Rechte ausüben möchtest oder Fragen zu dieser Erklärung hast, kontaktiere uns unter <strong>support@methys.com</strong> oder per Post an Methys, Daskalogianni 33, 73100 Chania, Kreta, Griechenland.</p>')
